export interface ChartHoverState {
  /** The index of the currently hovered data point, or null when nothing is hovered. */
  hoveredIndex: number | null
  /** The id of the chart that owns the current hover, or null when nothing is hovered. */
  hoveredChart: string | null
  /** True whenever there is an active hover (i.e. `hoveredIndex` is not null). */
  isHovered: boolean
  /** True only for the chart instance whose `chartId` matches `hoveredChart`. */
  isCurrentChart: boolean
  /** Whether hover state is synchronized across all chart instances. */
  syncHover: boolean
  /** Whether tooltip state is synchronized across all chart instances. */
  syncTooltip: boolean
}

export interface ChartHoverStateHook extends ChartHoverState {
  /** Set the hovered index for this chart. Updates local or global state based on `syncHover`. */
  setHover: (index: number | null) => void
  /** Clear the current hover. Resets local or global state based on `syncHover`. */
  clearHover: () => void
  /** Toggle hover synchronization across all instances. Disabling it also disables tooltip sync. */
  setSyncHover: (enabled: boolean) => void
  /** Toggle tooltip synchronization across all instances. Enabling it also enables hover sync. */
  setSyncTooltip: (enabled: boolean) => void
}

interface HoverPosition {
  hoveredIndex: number | null
  hoveredChart: string | null
}

interface SyncSettings {
  syncHover: boolean
  syncTooltip: boolean
}

const EMPTY_HOVER: HoverPosition = { hoveredIndex: null, hoveredChart: null }

/**
 * Read a stored boolean flag from localStorage. Returns false when the key is
 * absent, and throws when the stored value is not valid JSON so the caller can
 * decide how to handle corruption.
 */
function parseStoredBoolean(key: string): boolean {
  if (typeof window === 'undefined' || !window.localStorage) return false
  const raw = window.localStorage.getItem(key)
  if (raw === null) return false
  return JSON.parse(raw) === true
}

/**
 * Load the sync settings from localStorage. If either value is corrupted or not
 * JSON-parseable, both settings default to false and a warning is emitted.
 */
function loadSyncSettings(): SyncSettings {
  try {
    return {
      syncHover: parseStoredBoolean(HOVER_SYNC_STORAGE_KEY),
      syncTooltip: parseStoredBoolean(TOOLTIP_SYNC_STORAGE_KEY),
    }
  } catch (error) {
    console.warn('Failed to read chart hover sync settings from localStorage:', error)
    return { syncHover: false, syncTooltip: false }
  }
}

/**
 * Persist the sync settings to localStorage. If saving fails, the in-memory
 * state is left untouched (it was already updated by the caller) and a warning
 * is logged.
 */
function persistSyncSettings(settings: SyncSettings): void {
  try {
    if (typeof window === 'undefined' || !window.localStorage) return
    window.localStorage.setItem(HOVER_SYNC_STORAGE_KEY, JSON.stringify(settings.syncHover))
    window.localStorage.setItem(TOOLTIP_SYNC_STORAGE_KEY, JSON.stringify(settings.syncTooltip))
  } catch (error) {
    console.warn('Failed to save chart hover sync setting to localStorage:', error)
  }
}

// Module-level state shared across every hook instance.
let globalHover: HoverPosition = { ...EMPTY_HOVER }
let syncSettings: SyncSettings = loadSyncSettings()

const listeners = new Set<() => void>()

function emit(): void {
  listeners.forEach((listener) => listener())
}

/**
 * Manage hover interactions across multiple chart instances, with optional
 * synchronization of hover and tooltip state. Sync preferences persist across
 * page reloads via localStorage.
 */
export function useChartHoverState(chartId: string): ChartHoverStateHook {
  // Local hover position, used when hover sync is disabled.
  const [localHover, setLocalHover] = useState<HoverPosition>({ ...EMPTY_HOVER })

  // A dummy counter used to force a re-render when module-level state changes.
  const [, forceRender] = useState(0)

  // Subscribe to global state changes so this instance re-renders in sync.
  useEffect(() => {
    const listener = () => forceRender((n) => n + 1)
    listeners.add(listener)
    return () => {
      listeners.delete(listener)
    }
  }, [])

  // Re-hydrate sync settings from localStorage on mount so preferences applied
  // in another tab/session (or persisted across reloads) are reflected.
  useEffect(() => {
    const loaded = loadSyncSettings()
    if (loaded.syncHover !== syncSettings.syncHover || loaded.syncTooltip !== syncSettings.syncTooltip) {
      syncSettings = loaded
      emit()
    }
  }, [])

  const { syncHover, syncTooltip } = syncSettings
  const activeHover = syncHover ? globalHover : localHover
  const hoveredIndex = activeHover.hoveredIndex
  const hoveredChart = activeHover.hoveredChart
