        setLocalHover({ hoveredIndex: index, hoveredChart: chartId })
      }
    },
    [chartId]
  )

  const clearHover = useCallback(() => {
    if (syncSettings.syncHover) {
      globalHover = { ...EMPTY_HOVER }
      emit()
    } else {
      setLocalHover({ ...EMPTY_HOVER })
    }
