  const setSyncHover = useCallback((enabled: boolean) => {
    // No-op if the requested state already matches the current state.
    if (syncSettings.syncHover === enabled) return

    const next: SyncSettings = {
      syncHover: enabled,
      // Disabling hover sync also disables tooltip sync.
      syncTooltip: enabled ? syncSettings.syncTooltip : false,
    }

    // Update in-memory state first so it survives a localStorage failure.
    syncSettings = next
    persistSyncSettings(next)
    emit()
