    if (next.syncHover === syncSettings.syncHover && next.syncTooltip === syncSettings.syncTooltip) {
      return
    }

    // Update in-memory state first so it survives a localStorage failure.
    syncSettings = next
    persistSyncSettings(next)
    emit()
  }, [])

  return {
    hoveredIndex,
    hoveredChart,
    isHovered,
    isCurrentChart,
    syncHover,
    syncTooltip,
    setHover,
    clearHover,
    setSyncHover,
    setSyncTooltip,
  }
}

